function mergeBlockers(pr, r) {
    const reasons = [];
    if (pr.state === 'Draft') reasons.push('This pull request is still a draft');
    if (pr.state !== 'Open') reasons.push('This pull request is not open');
    const revs = effectiveReviews(pr);
    if (revs.some((x) => x.status === 'Request changes')) reasons.push('Changes requested by a reviewer');
    const prot = protectionFor(r, pr.base);
    if (prot) {
      const approvals = revs.filter((x) => x.status === 'Approve' && x.reviewer !== pr.author).length;
      if (prot.approval && approvals < 1) reasons.push('Review required by branch protection');
      if (prot.check && (!pr.check || pr.check.status !== 'success')) reasons.push('Required status check test is not successful');
    }
    return reasons;
  }

function({ form }) {
      const { pr } = currentPr();
      const u = me();
      if (!pr || !u) return;
      const decision = form.decision || 'Comment';
      pr.reviews = pr.reviews || [];
      const rec = { id: ARC.uid('rv'), reviewer: u.username, status: decision === 'Approve' ? 'Approved' : (decision === 'Request changes' ? 'Changes requested' : 'Commented'), summary: form.summary || '', ago: 'just now' };
      const existing = pr.reviews.findIndex((x) => x.reviewer === u.username);
      if (existing >= 0) pr.reviews[existing] = rec;
      else pr.reviews.push(rec);
      ARC.save();
      ARC.closeDialog();
      ARC.render();
    }

