        ui().signinError = 'Invalid credentials';
        ui().signinUser = form.username;
        ARC.render();
        return;
      }
      ui().signinError = null; ui().signinUser = null;
      S().session = u.id;
      ARC.save();
      ARC.navigate('#/');
