    signup({ form }) {
      const errors = { username: '', email: '', password: '', confirm: '', terms: '' };
      const username = String(form.username || '').trim();
      const email = String(form.email || '').trim();
      if (!validUsername(username)) errors.username = 'Username format is invalid';
      else if (findUser(username)) errors.username = 'Username already exists';
      if (!validEmail(email)) errors.email = 'Email format is invalid';
      const pwOk = validPassword(form.password);
      if (!pwOk) errors.password = 'Password requirements are not satisfied';
      else if (form.password !== form.confirm) errors.confirm = 'Password confirmation does not match';
      if (form.terms !== 'yes') errors.terms = 'Agree to terms is required';
      ui().signup = { username, email };
      ARC.save();
      showSignupErrors(errors);
      // Password inputs must not redisplay a rejected value; the rest of the form stays as typed.
      if (errors.password) {
        const pw = document.getElementById('su-pass'), cf = document.getElementById('su-confirm');
        if (pw) pw.value = '';
        if (cf) cf.value = '';
      }
      if (Object.values(errors).some(Boolean)) return;
      S().users.push({ id: ARC.uid('u'), username, email, password: form.password, verified: true });
      ui().signup = null;
      ARC.save();
      ARC.navigate('#/login');
      ARC.notify('Registration successful');
    },
    'send-reset'({ form }) {
      ui().resetEmail = form.email;
      ui().resetStep = 2;
      ui().resetError = null;
      ARC.render();
