      if (!validPassword(form.password)) { ui().resetError = 'Password requirements are not satisfied'; ARC.render(); return; }
      if (form.password !== form.confirm) { ui().resetError = 'Password confirmation does not match'; ARC.render(); return; }
      ui().resetError = null;
      if (target) { target.password = form.password; ARC.save(); }
      ui().resetStep = 1;
      ARC.render();
