    // --- branches / clone ---
    'branch-menu'({ el }) {
      const r = findRepo(ARC.route().params[0], ARC.route().params[1]);
      const branch = (ui().branch && ui().branch[r.id]) || r.defaultBranch;
      const host = el.parentElement;
      ARC.openPopover(host, `<input type="text" id="branch-find" aria-label="Find branch" placeholder="Find branch" data-change="branch-filter">
<div role="listbox" aria-label="Branches" class="branch-list">
${branchesOf(r).map((b) => `<div role="option" data-action="switch-branch" data-branch="${esc(b.name)}" aria-selected="${b.name === branch}">${esc(b.name)}</div>`).join('')}
<div role="option" data-action="create-branch" data-create data-branch="" hidden>Create branch: </div>
</div>
<p class="invalid" data-invalid hidden>Invalid branch</p>
<p class="no-match" data-nomatch hidden>No matching branch</p>`, { kind: 'buttons' });
    },
    'branch-filter'({ el }) {
      const q = String(el.value || '').trim();
      const pop = el.closest('[data-popover]');
      const lower = q.toLowerCase();
      let matching = 0;
      for (const o of pop.querySelectorAll('[role="option"][data-branch]:not([data-create])')) {
        const hit = !q || o.textContent.toLowerCase().includes(lower);
        o.hidden = !hit;
        if (hit) matching += 1;
      }
      const create = pop.querySelector('[data-create]');
      const invalid = pop.querySelector('[data-invalid]');
      const nomatch = pop.querySelector('[data-nomatch]');
      const ok = q && validBranchName(q) && !branchesOf(findRepo(ARC.route().params[0], ARC.route().params[1])).some((b) => b.name === q);
      create.hidden = !ok;
      create.textContent = 'Create branch: ' + q;
      create.dataset.branch = q;
      invalid.hidden = !(q && !validBranchName(q));
      if (nomatch) nomatch.hidden = !(q && matching === 0);
    },
    'switch-branch'({ el }) {
      const r = findRepo(ARC.route().params[0], ARC.route().params[1]);
      ui().branch = ui().branch || {};
      ui().branch[r.id] = el.dataset.branch;
      ARC.render();
