  <button type="button" role="tab" data-action="clone-tab" data-proto="SSH" aria-selected="${proto === 'SSH'}">SSH</button>
</div>
<input type="text" id="clone-value" aria-label="Clone value" value="${esc(value)}">
<button type="button" aria-label="Copy clone value" data-action="copy-clone" data-value="${esc(value)}">Copy</button>`, { kind: 'buttons' });
