    },
    'new-file'() {
      const r = findRepo(ARC.route().params[0], ARC.route().params[1]);
      const branch = (ui().branch && ui().branch[r.id]) || r.defaultBranch;
      ARC.navigate(repoHash(r) + '/new-file/' + encodeURIComponent(branch));
    },
    'commit-changes'({ form, el }) {
      const r = repos().find((x) => x.id === el.dataset.repo);
      const branch = el.dataset.branch;
      const u = me();
      const path = String(form.path || '').trim();
      if (!canWrite(r, u)) { ui().fileError = 'Access denied'; ARC.render(); return; }
      if (!validFilePath(path)) { ui().fileError = 'Invalid file path'; ARC.render(); return; }
      if (!String(form.message || '').trim() || String(form.message).trim().length > 72) { ui().fileError = 'Commit message is required'; ARC.render(); return; }
      if (fileAt(r, branch, path) && !el.dataset.path) { ui().fileError = 'Invalid file path'; ARC.render(); return; }
      ui().fileError = null;
      const head = branchHead(r, branch);
      const commit = { id: ARC.uid('c'), repoId: r.id, hash: ARC.uid('h').slice(-7), message: String(form.message).trim(), author: u.username, ago: 'just now', parent: head ? head.id : null, files: [{ path, additions: String(form.content || '').split('\n').length, deletions: 0 }] };
      S().commits.push(commit);
      const existing = fileAt(r, branch, path);
      if (existing) existing.content = form.content || '';
      else S().files.push({ id: ARC.uid('f'), repoId: r.id, branch, path, content: form.content || '' });
      const br = branchesOf(r).find((b) => b.name === branch);
      if (br) br.head = commit.id;
      ARC.save();
      ARC.navigate(blobHash(r, branch, path));
    },

    // --- issues ---
    'issue-state'({ el }) { ui().issueState = el.dataset.state; ui().issueQuery = ''; ARC.save(); ARC.render(); },
    'issue-label'({ el }) { ui().issueLabel = ui().issueLabel === el.dataset.label ? '' : el.dataset.label; ARC.save(); ARC.render(); },
    'issue-search'({ el }) { ui().issueQuery = el.value; ui().focus = 'issue-search'; ARC.save(); ARC.render(); },
    'submit-issue'({ form, el }) {
      const r = repos().find((x) => x.id === el.dataset.repo);
      const title = String(form.title || '').trim();
      if (!title) { ui().newIssueError = 'Title is required'; ARC.render(); return; }
      if (title.length > 256) { ui().newIssueError = 'Title is required'; ARC.render(); return; }
      ui().newIssueError = null;
      const nums = issuesOf(r).map((i) => i.number);
