    // --- repository creation / settings ---
    'create-repo'({ form }) {
      const u = me();
      const name = String(form.name || '').trim();
      const ownerId = form.owner;
      const isOrg = !!findOrg(ownerId);
      const e = {};
      if (!name) e.name = 'Repository name is required';
      else if (!/^[A-Za-z0-9._-]+$/.test(name)) e.name = 'Repository name is invalid';
      else if (repos().some((r) => r.name === name && r.ownerId === ownerId && r.ownerType === (isOrg ? 'org' : 'user'))) e.name = 'Repository name already exists';
      ui().newRepo = { name, description: form.description || '' };
      ui().newRepoErrors = e;
      if (Object.keys(e).length) { ARC.render(); return; }
      const repo = {
        id: ARC.uid('r'), ownerType: isOrg ? 'org' : 'user', ownerId,
        orgId: isOrg ? ownerId : null, name, description: form.description || '',
        visibility: form.visibility || 'Public', defaultBranch: 'main', updated: 'just now', sourceId: null
      };
      S().repos.push(repo);
      S().branches.push({ id: ARC.uid('b'), repoId: repo.id, name: 'main', head: null });
      if (form.readme === 'yes') {
        const commit = { id: ARC.uid('c'), repoId: repo.id, hash: ARC.uid('h').slice(-7), message: 'Initial commit', author: u.username, ago: 'just now', parent: null, files: [{ path: 'README.md', additions: 1, deletions: 0 }] };
        S().commits.push(commit);
        S().files.push({ id: ARC.uid('f'), repoId: repo.id, branch: 'main', path: 'README.md', content: '# ' + name + '\n' });
        const br = branchesOf(repo).find((b) => b.name === 'main');
        if (br) br.head = commit.id;
      }
      ui().newRepo = null; ui().newRepoErrors = null;
      ARC.save();
      ARC.navigate(repoHash(repo));
    },
    'fork-open'() {
      const r = currentRepo();
