      ui().forkError = null;
      ARC.save();
      ARC.navigate(repoHash(r) + '/fork');
    },
    'create-fork'({ form }) {
      const u = me();
      const src = currentRepo();
      if (!u || !src) return;
      const name = String(form.name || '').trim();
      if (!validUsername(name)) { ui().forkError = 'Repository name is invalid'; ARC.save(); ARC.render(); return; }
      if (repos().some((r) => r.name === name && r.ownerType === 'user' && r.ownerId === u.id)) {
        ui().forkError = 'Repository name already exists';
        ARC.save();
        ARC.render();
        return;
      }
      ui().forkError = null;
      const repo = { id: ARC.uid('r'), ownerType: 'user', ownerId: u.id, orgId: null, name, description: 'Fork of ' + src.name, visibility: src.visibility === 'Private' ? 'Private' : (form.visibility || 'Public'), defaultBranch: 'main', updated: 'just now', sourceId: src.id };
      S().repos.push(repo);
      for (const b of branchesOf(src)) S().branches.push({ id: ARC.uid('b'), repoId: repo.id, name: b.name, head: b.head });
      for (const f of (S().files || []).filter((x) => x.repoId === src.id)) S().files.push({ id: ARC.uid('f'), repoId: repo.id, branch: f.branch, path: f.path, content: f.content });
      ARC.save();
      ARC.navigate(repoHash(repo));
