      const u = me();
      const name = el.dataset.branch;
      if (!canWrite(r, u) || !validBranchName(name) || branchesOf(r).some((b) => b.name === name)) return;
      const cur = (ui().branch && ui().branch[r.id]) || r.defaultBranch;
      const head = branchHead(r, cur);
      S().branches.push({ id: ARC.uid('b'), repoId: r.id, name, head: head ? head.id : null });
      ui().branch = ui().branch || {};
      ui().branch[r.id] = name;
      ARC.save();
      ARC.render();
