function () {
    const id = ui().focus;
    if (id && !ARC.dialogOpen) {
      const el = document.getElementById(id);
      if (el && typeof el.focus === 'function') {
        el.focus();
        try { el.setSelectionRange(el.value.length, el.value.length); } catch (e) { /* not a text field */ }
      }
    }
  }

function diffSummary(files) {
    const a = files.reduce((n, f) => n + (f.additions || 0), 0);
    const d = files.reduce((n, f) => n + (f.deletions || 0), 0);
    return `${a} additions, ${d} deletions`;
  }

function commitsBetween(r, base, compare) {
    const baseHead = branchHead(r, base);
    const cmpHead = branchHead(r, compare);
    const out = [];
    let cur = cmpHead, guard = 0;
    while (cur && (!baseHead || cur.id !== baseHead.id) && guard++ < 50) { out.push(cur); cur = cur.parent ? commitById(cur.parent) : null; }
    return out;
  }

function repoHeader(r, active, opts) {
    const h = repoHash(r);
    const tabs = [['code', 'Code', h], ['issues', 'Issues', h + '/issues'], ['pulls', 'Pull requests', h + '/pulls'], ['settings', 'Settings', h + '/settings']];
    const u = me();
    const role = effectiveRole(r, u);
    const alt = (r.ownerType === 'user' && r.orgId && findOrg(r.orgId)) ? findOrg(r.orgId).name + '/' + r.name : '';
    const forkLine = r.sourceId ? (() => { const src = repos().find((x) => x.id === r.sourceId); return src ? `<p class="forked">Forked from <a href="${repoHash(src)}">${esc(src.name)}</a></p>` : ''; })() : '';
    const branch = (ui().branch && ui().branch[r.id]) || r.defaultBranch;
    const write = canWrite(r, u);
    const toolbar = `<div class="repo-toolbar">
  <span class="pick"><button type="button" data-action="branch-menu">Branch ${esc(branch)}</button></span>
  <span class="pick"><button type="button" data-action="clone-menu">Code</button></span>
  ${u ? `<span class="pick"><button type="button" data-action="fork-open">Fork</button></span>` : ''}
  ${write ? `<span class="pick"><button type="button" data-action="add-file-menu">Add file</button></span>` : ''}
</div>`;
    const common = `<h1>${esc(repoFull(r))}</h1>
${alt ? `<p class="repo-path">${esc(alt)}</p>` : ''}
<p>${marker(r)} ${role ? esc(role) + ' permission' : 'no permission'}</p>
<p>${esc(r.description || '')}</p>
${forkLine}
<nav class="repo-nav">${tabs.map(([k, label, href]) => `<a href="${href}"${active === k ? ' aria-current="page"' : ''}>${label}</a>`).join('')}</nav>`;
    if (active === 'code') return common + toolbar;
    return common;
  }

function effectiveReviews(pr) {
    const map = new Map();
    for (const rv of (pr.reviews || [])) map.set(rv.reviewer, rv);
    return [...map.values()];
  }

function currentPr() {
    const r = currentRepo();
    if (!r) return { r: null, pr: null };
    const p = ARC.route().params || [];
    const pr = prsOf(r).find((x) => String(x.number) === String(p[3])) || null;
    return { r, pr };
  }

function currentRepo() {
    const p = ARC.route().params || [];
    return findRepo(p[0], p[1]);
  }

function findRepo(owner, name) {
    return repos().find((r) => r.name === name && ownerName(r) === owner) || null;
  }

function ownerName(r) {
    if (!r) return '';
    if (r.ownerType === 'org') { const o = findOrg(r.ownerId); return o ? o.name : r.ownerId; }
    return uname(r.ownerId) || r.ownerId;
  }

bindings.setup:
