ARC.route = function () { return { name: 'r', params: ['alice-dev', 'acme-docs', 'pull', '9'] }; };
ARC.currentUser = function () { return (ARC.state.users || []).find(function (u) { return u.id === ARC.state.session; }) || null; };
ARC.state.prs.push({ id: 'p9', repoId: 'r1', number: 9, title: 'Release onboarding for team review', body: 'Ready for release.', state: 'Open', base: 'release', compare: 'onboarding', author: 'alice', ago: 'just now', reviewers: [], reviews: [], comments: [], activity: [], check: { status: 'success', setter: 'alice-dev', ago: 'just now' }, inline: [] });

bindings.precondition:
const st = ARC.state;
const r1 = st.repos.find(function (r) { return r.id === 'r1'; });
const pr = st.prs.find(function (p) { return p.id === 'p9'; });
assert.ok(r1 && pr, 'the seeded repository and the fixture pull request exist');
assert.strictEqual(pr.state, 'Open');
assert.strictEqual(pr.base, 'release');
assert.strictEqual(pr.compare, 'onboarding');
assert.ok(st.branches.some(function (b) { return b.repoId === 'r1' && b.name === 'release'; }));
assert.ok(st.branches.some(function (b) { return b.repoId === 'r1' && b.name === 'onboarding'; }));
assert.ok(!st.protections.some(function (p) { return p.repoId === 'r1' && p.branch === 'release'; }), 'the target branch is unprotected, so only the review decision can block the merge');
assert.strictEqual(pr.author, 'alice');
assert.strictEqual(ARC.currentUser().username, 'alice-dev');
assert.notStrictEqual(ARC.currentUser().username, pr.author, 'the reviewer is not the PR author');
assert.strictEqual(pr.check.status, 'success');
assert.strictEqual(pr.reviews.length, 0, 'the reviewer has no prior decision on this PR');
assert.strictEqual(mergeBlockers(pr, r1).length, 0, 'control: nothing blocks this pull request before the review');

