      const teams = new Set(teamsOf(orgId).map((t) => t.id));
      S().teamMembers = (S().teamMembers || []).filter((tm) => !(tm.userId === id && teams.has(tm.teamId)));
      const repoIds = new Set(repos().filter((r) => r.orgId === orgId).map((r) => r.id));
      S().grants = (S().grants || []).filter((g) => !(g.subjectType === 'user' && g.subjectId === id && repoIds.has(g.repoId)));
      ARC.save();
      ARC.closeDialog();
      ARC.render();
