      }
      const rest = p.slice(2);
      const section = rest[0] || 'code';
      if (section === 'issues') {
        if (rest[1] === 'new') return this.issueNew(r, u);
        if (rest[1]) return this.issueDetail(r, rest[1], u);
        return this.issueList(r, u);
      }
      if (section === 'pulls') {
        if (rest[1] === 'compare') return this.prCompare(r, u);
        if (rest[1]) return this.prDetail(r, rest[1], u, 'conversation');
        return this.prList(r, u);
      }
      if (section === 'pull') return this.prDetail(r, rest[1], u, rest[2] || 'conversation');
      if (section === 'commits') return this.commitList(r, u);
      if (section === 'commit') return this.commitDetail(r, rest[1], u);
      if (section === 'tree') return this.treeView(r, rest[1], rest.slice(2).join('/'), u);
      if (section === 'blob') return this.blobView(r, rest[1], rest.slice(2).join('/'), u);
      if (section === 'edit') return this.editFile(r, rest[1], rest.slice(2).join('/'), u);
