      accountMenuContent: null
    },

    screen(route) {
      const sx = this.screens;
      const p = route.params || [];
      switch (route.name) {
        case 'home': return sx.home.call(this);
        case 'explore': return sx.explore.call(this);
        case 'login': case 'signin': return sx.signin.call(this);
        case 'signup': return sx.signup.call(this);
        case 'forgot': return sx.forgot.call(this);
        case 'settings': return p[0] === 'password' ? sx.passwordSettings.call(this) : sx.settings.call(this);
        case 'search': return sx.search.call(this);
        case 'orgs': return sx.orgs.call(this);
        case 'new-org': return sx.newOrg.call(this);
        case 'new': case 'new-repo': return sx.repoNew.call(this);
        case 'signout': return sx.home.call(this);
        case 'org': return this.orgRoute(p);
        case 'r': return this.repoRoute(p);
        default: return sx.home.call(this);
      }
    },

    // ---------- organization routes ----------
    orgRoute(p) {
      const org = findOrg(p[0]);
      if (!org) return `<h1>Organization not found</h1><p><a href="#/">Home</a></p>`;
      const u = me();
      const sub = p[1] || 'repositories';
      const tabs = `<nav class="tabs">
  <a href="#/org/${esc(org.id)}/repositories"${sub === 'repositories' ? ' aria-current="page"' : ''}>Repositories</a>
  <a href="#/org/${esc(org.id)}/people"${sub === 'people' ? ' aria-current="page"' : ''}>People</a>
  <a href="#/org/${esc(org.id)}/teams"${sub === 'teams' ? ' aria-current="page"' : ''}>Teams</a>
</nav>`;
      const head = `<h1>${esc(org.name)}</h1>${tabs}`;
      if (sub === 'people') return head + this.orgPeople(org, u);
      if (sub === 'teams') return head + this.orgTeams(org, u);
      if (sub === 'new-team') return head + this.teamNew(org, u);
      if (sub === 'team') return this.teamPage(org, teamById(p[2]), u, p[3] || 'members');
      return head + this.orgRepos(org, u);
    },
    orgRepos(org, u) {
      const q = (ui().repoFilter || '').toLowerCase();
      const vis = ui().repoVisibility || 'All';
      const list = repos().filter((r) => r.orgId === org.id && canView(r, u))
        .filter((r) => vis === 'All' || r.visibility === vis)
        .filter((r) => !q || r.name.toLowerCase().includes(q));
      return `<h2>Repositories</h2>
<label for="find-repo">Find a repository</label>
<input id="find-repo" name="find" type="text" placeholder="Find a repository" data-change="repo-filter" value="${esc(ui().repoFilter || '')}">
<div class="filters">
  ${['All', 'Public', 'Private'].map((v) => `<button type="button" data-action="repo-visibility" data-vis="${v}" aria-pressed="${vis === v}">${v}</button>`).join('')}
</div>
${list.map(repoRowLink).join('') || '<p>No results</p>'}`;
    },
    orgPeople(org, u) {
      const owner = isOrgOwner(org.id, u);
      const rows = orgMembers(org.id).map((m) => {
        const name = uname(m.userId);
        return `<article class="member-row" data-id="${esc(m.userId)}">
  <h3>${esc(name)}</h3>
  <p>${esc(m.role)}</p>
  ${owner ? `<span class="pick"><button type="button" data-action="member-menu" data-id="${esc(m.userId)}">Member menu ${esc(name)}</button></span>` : ''}
</article>`;
      }).join('');
      return `<h2>People</h2>
${ui().orgMemberError ? err(ui().orgMemberError) : ''}
<span class="pick"><button type="button" data-action="add-member-open">Add member</button></span>
${rows || '<p>No results</p>'}`;
    },
    orgTeams(org, u) {
      const owner = isOrgOwner(org.id, u);
      const rows = teamsOf(org.id).map((t) => `<article class="team-row" data-id="${esc(t.id)}">
  <h3><a href="#/org/${esc(org.id)}/team/${esc(t.id)}">${esc(t.name)}</a></h3>
  ${t.parentId ? `<p>Parent team: ${esc((teamById(t.parentId) || {}).name || '')}</p>` : '<p>No parent team</p>'}
</article>`).join('');
      return `<h2>Teams</h2>
${owner ? `<p><a href="#/org/${esc(org.id)}/new-team">New team</a></p>` : ''}
${rows || '<p>No results</p>'}`;
    },
    teamNew(org, u) {
      if (!isOrgOwner(org.id, u)) return `<h2>New team</h2><p>Access denied</p>`;
      const e = ui().newTeamErrors || {};
      return `<h2>New team</h2>
<form data-action="create-team" data-org="${esc(org.id)}">
  <label for="nt-name">Team name</label>
  <input id="nt-name" name="name" type="text" placeholder="Team name" value="${esc((ui().newTeam || {}).name || '')}">
  ${err(e.name)}
  <label for="nt-desc">Description</label>
  <input id="nt-desc" name="description" type="text" placeholder="Description">
  <label for="nt-parent">Parent team</label>
  <select id="nt-parent" name="parent">
    <option value="">None</option>
    ${teamsOf(org.id).map((t) => `<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}
  </select>
  <button type="submit">Create team</button>
</form>`;
    },
    teamPage(org, team, u, tab) {
      if (!team) return `<h1>Team not found</h1>`;
      const owner = isOrgOwner(org.id, u);
      const tabs = `<nav class="tabs">
  <a href="#/org/${esc(org.id)}/team/${esc(team.id)}"${tab === 'members' ? ' aria-current="page"' : ''}>Members</a>
  <a href="#/org/${esc(org.id)}/team/${esc(team.id)}/settings"${tab === 'settings' ? ' aria-current="page"' : ''}>Settings</a>
</nav>`;
      const head = `<h1>${esc(org.name)}/${esc(team.name)}</h1>${tabs}`;
      if (tab === 'settings') {
        const e = ui().teamSettingsError;
        return head + `${e ? err(e) : ''}
<form data-action="save-team-settings" data-team="${esc(team.id)}">
  <label for="pt-parent">Parent team</label>
  <select id="pt-parent" name="parent">
    <option value="">None</option>
    ${teamsOf(org.id).filter((t) => t.id !== team.id).map((t) => `<option value="${esc(t.id)}"${team.parentId === t.id ? ' selected' : ''}>${esc(t.name)}</option>`).join('')}
  </select>
  <button type="submit">Save</button>
</form>`;
      }
      const members = teamMembersOf(team.id).map((tm) => {
        const name = uname(tm.userId);
        return `<article class="member-row" data-id="${esc(tm.userId)}"><h3>${esc(name)}</h3>${owner ? `<span class="pick"><button type="button" data-action="remove-team-member" data-id="${esc(tm.userId)}">Remove ${esc(name)}</button></span>` : ''}</article>`;
      }).join('');
      return head + `${ui().teamMemberError ? err(ui().teamMemberError) : ''}
${owner ? `<span class="pick"><button type="button" data-action="add-team-member-open">Add member</button></span>` : ''}
${members || '<p>No members</p>'}`;
    },

    // ---------- repository routes ----------
    repoRoute(p) {
      const owner = p[0] || '', name = p[1] || '';
      const r = findRepo(owner, name);
      if (!r) return `<h1>Repository not found</h1><p><a href="#/">Home</a></p>`;
      const u = me();
      if (!canView(r, u)) {
        if (!u) return `<h1>Sign in required</h1><p>Access denied</p><p><a href="#/signin">Sign in</a></p>`;
        return `<h1>Access denied</h1><p>You do not have permission to view this repository.</p>`;
      }
      const rest = p.slice(2);
      const section = rest[0] || 'code';
      if (section === 'issues') {
        if (rest[1] === 'new') return this.issueNew(r, u);
        if (rest[1]) return this.issueDetail(r, rest[1], u);
        return this.issueList(r, u);
      }
      if (section === 'pulls') {
        if (rest[1] === 'compare') return this.prCompare(r, u);
        if (rest[1]) return this.prDetail(r, rest[1], u, 'conversation');
        return this.prList(r, u);
      }
      if (section === 'pull') return this.prDetail(r, rest[1], u, rest[2] || 'conversation');
      if (section === 'commits') return this.commitList(r, u);
      if (section === 'commit') return this.commitDetail(r, rest[1], u);
      if (section === 'tree') return this.treeView(r, rest[1], rest.slice(2).join('/'), u);
      if (section === 'blob') return this.blobView(r, rest[1], rest.slice(2).join('/'), u);
      if (section === 'edit') return this.editFile(r, rest[1], rest.slice(2).join('/'), u);
      if (section === 'new-file') return this.newFile(r, rest[1], u);
      if (section === 'search') return this.codeSearch(r, u);
      if (section === 'settings') return this.repoSettings(r, u, rest[1], rest[2]);
      if (section === 'fork') return this.forkPage(r, u);
      return this.codePage(r, u);
    },
    codePage(r, u) {
      const branch = (ui().branch && ui().branch[r.id]) || r.defaultBranch;
      const commits = (S().commits || []).filter((c) => c.repoId === r.id);
      const write = canWrite(r, u);
      return `${repoHeader(r, 'code')}
<p class="commit-count"><a href="${repoHash(r)}/commits">Commits</a> <span class="count">${commits.length}</span></p>
${fileList(r, branch, '')}
${write ? `<p><span class="pick"><button type="button" data-action="add-file-menu">Create new file</button></span></p>` : ''}`;
    },
    treeView(r, branch, dir, u) {
      return `${repoHeader(r, 'code')}
<p class="crumbs">${esc(ownerName(r))} / ${esc(r.name)} / <a href="${dirHash(r, branch, '')}">${esc(branch)}</a>${dir ? ' / ' + dir.split('/').map((x) => esc(x)).join(' / ') : ''}</p>
${fileList(r, branch, dir)}`;
    },
    blobView(r, branch, path, u) {
      const f = fileAt(r, branch, path);
      if (!f) return `${repoHeader(r, 'code')}<p>File not found.</p>`;
      const write = canWrite(r, u);
      return `${repoHeader(r, 'code')}
<p class="crumbs">${esc(ownerName(r))} / ${esc(r.name)} / <a href="${dirHash(r, branch, '')}">${esc(branch)}</a>${path.split('/').slice(0, -1).map((x) => ' / ' + esc(x)).join('')}</p>
<h2>${esc(path)}</h2>
<p class="branch-line">Branch ${esc(branch)}</p>
<p class="commit-count"><a href="${repoHash(r)}/commits">Commits</a></p>
<pre class="file-content">${esc(f.content)}</pre>
${write ? `<p><a href="${repoHash(r)}/edit/${encodeURIComponent(branch)}/${path.split('/').map(encodeURIComponent).join('/')}">Edit</a></p>` : ''}`;
    },
    commitList(r, u) {
      const commits = (S().commits || []).filter((c) => c.repoId === r.id);
      return `${repoHeader(r, 'code')}
<h2>Commits</h2>
${commits.map((c) => `<article class="commit-row" data-id="${esc(c.id)}">
  <h3><a href="${repoHash(r)}/commit/${esc(c.hash)}">${esc(c.hash)}</a></h3>
  <p><a href="${repoHash(r)}/commit/${esc(c.hash)}">${esc(c.message)}</a></p>
  <p>${esc(c.author)} committed <span class="ago">${esc(c.ago)}</span></p>
</article>`).join('') || '<p>No commits</p>'}`;
    },
    commitDetail(r, hash, u) {
      const c = (S().commits || []).find((x) => x.repoId === r.id && x.hash === hash);
      if (!c) return `${repoHeader(r, 'code')}<p>Commit not found.</p>`;
      const files = c.files || [];
      return `${repoHeader(r, 'code')}
<h2>Commit ${esc(c.hash)}</h2>
<p>${esc(c.message)}</p>
<p>${esc(c.author)} committed <span class="ago">${esc(c.ago)}</span></p>
<p class="summary">${diffSummary(files)}</p>
<h2>Changed files</h2>
${files.map((f) => `<article class="diff-file">
  <h3>${esc(f.path)}</h3>
  <p class="summary">${f.additions} additions, ${f.deletions} deletions</p>
  ${(f.lines || []).map((l) => `<div class="diff-line ${l.type}"><code>${esc(l.text)}</code></div>`).join('')}
</article>`).join('')}
<p><button type="button" data-action="compare-run">Compare</button></p>`;
    },
    editFile(r, branch, path, u) {
      const f = fileAt(r, branch, path);
      if (!canWrite(r, u)) return `${repoHeader(r, 'code')}<p>Access denied</p>`;
      return `${repoHeader(r, 'code')}
<h2>Edit file</h2>
${err(ui().fileError)}
<form data-action="commit-changes" data-repo="${esc(r.id)}" data-branch="${esc(branch)}" data-path="${esc(path)}">
  <label for="ef-path">File name</label>
  <input id="ef-path" name="path" type="text" placeholder="File name" value="${esc(path)}">
  <label for="ef-content">File contents</label>
  <textarea id="ef-content" name="content" rows="10" aria-label="File contents">${esc(f ? f.content : '')}</textarea>
  <label for="ef-message">Commit message</label>
  <input id="ef-message" name="message" type="text" placeholder="Commit message">
  <button type="submit">Commit changes</button>
</form>`;
    },
    newFile(r, branch, u) {
      if (!canWrite(r, u)) return `${repoHeader(r, 'code')}<p>Access denied</p>`;
      return `${repoHeader(r, 'code')}
<h2>Create new file</h2>
${err(ui().fileError)}
<form data-action="commit-changes" data-repo="${esc(r.id)}" data-branch="${esc(branch)}" data-path="">
  <label for="nf-path">File name</label>
  <input id="nf-path" name="path" type="text" placeholder="File name" value="${esc((ui().newFileName || ''))}">
  <label for="nf-content">File contents</label>
  <textarea id="nf-content" name="content" rows="10" aria-label="File contents"></textarea>
  <label for="nf-message">Commit message</label>
  <input id="nf-message" name="message" type="text" placeholder="Commit message">
  <button type="submit">Commit changes</button>
</form>`;
    },
    codeSearch(r, u) {
      const q = String(ui().codeQuery || '');
      const path = String(ui().codePath || '');
      const branch = (ui().branch && ui().branch[r.id]) || r.defaultBranch;
      const lower = q.toLowerCase();
      const hits = [];
      if (lower) {
        for (const f of filesOf(r, branch)) {
          if (path && !f.path.startsWith(path)) continue;
          if (f.content.toLowerCase().includes(lower)) hits.push(f);
        }
      }
      const types = `<nav class="filters">
  <a href="${repoHash(r)}/search" aria-current="page">Code</a>
  <a href="${repoHash(r)}/issues">Issues</a>
  <a href="${repoHash(r)}/pulls">Pull requests</a>
</nav>`;
      return `${repoHeaderPlain(r)}${types}
<p>Search: <span class="query">${esc(q)}</span></p>
<label for="path-filter">Path</label>
<input id="path-filter" name="path" type="text" placeholder="Path" data-change="code-path" value="${esc(ui().codePath || '')}">
${q && !hits.length ? '<p>No code results</p>' : ''}
${hits.map((f) => `<article class="code-hit" data-id="${esc(f.id)}">
  <h3><a href="${blobHash(r, branch, f.path)}">${esc(f.path.split('/').pop())}</a></h3>
  <p class="path">${esc(f.path)}</p>
  <p class="branch-line">Branch ${esc(branch)}</p>
  <pre>${esc(snippet(f.content, lower))}</pre>
</article>`).join('')}`;
