  <p><label><input type="radio" name="visibility" value="Public" checked> Public</label></p>
  <p><label><input type="radio" name="visibility" value="Private"> Private</label></p>
  <label for="cv-name">Repository name</label>
  <input id="cv-name" name="name" type="text" placeholder="Repository name">
