  <textarea id="ed-desc" name="body" rows="6" aria-label="Issue description">${esc(issue.body || '')}</textarea>
  <button type="submit">Save issue description</button>
  <button type="button" data-action="arc:close">Cancel</button>
</form>`, { title: 'Edit issue description' });
    },
    'save-desc'({ form, el }) {
      const issue = (S().issues || []).find((x) => x.id === el.dataset.issue);
      issue.body = form.body || '';
      issue.activity.push({ id: ARC.uid('a'), text: (me() || {}).username + ' edited the description', ago: 'just now' });
      ARC.save();
      ARC.closeDialog();
      ARC.render();
    },
    'add-comment'({ el }) {
