${members.map((name) => `<div role="option" data-action="toggle-assignee" data-name="${esc(name)}" aria-selected="${(issue.assignees || []).some((id) => uname(id) === name)}">${esc(name)}</div>`).join('')}`, { kind: 'buttons' });
