    },
    'toggle-reaction'({ el }) {
      const issue = (S().issues || []).find((i) => (i.comments || []).some((c) => c.id === el.dataset.comment));
      const c = issue.comments.find((x) => x.id === el.dataset.comment);
      c.reactions = c.reactions || [];
      const user = (me() || {}).username;
      const idx = c.reactions.findIndex((rx) => rx.user === user && rx.type === el.dataset.type);
      if (idx >= 0) c.reactions.splice(idx, 1);
