    // --- pull requests ---
    'pr-state'({ el }) { ui().prState = el.dataset.state; ARC.save(); ARC.render(); },
    'pr-author'({ el }) { ui().prAuthor = el.value; ui().focus = 'pr-author'; ARC.save(); ARC.render(); },
    'compare-change'({ el }) {
      const form = el.closest('form');
      if (!form) return;
      const data = new FormData(form);
      ui().cmpBase = String(data.get('base') || '');
      ui().cmpCompare = String(data.get('compare') || '');
      ARC.render();
    },
    'compare-submit'({ form }) {
      ui().cmpBase = String((form && form.base) || '');
      ui().cmpCompare = String((form && form.compare) || '');
      ARC.render();
    },
    'pr-form-open'({ el }) {
      const draft = el.dataset.draft === 'yes';
      const label = draft ? 'Create draft pull request' : 'Create pull request';
      ARC.openDialog(`<form data-action="create-pr" data-draft="${draft ? 'yes' : 'no'}">
  <label for="np-title">Title</label>
  <input id="np-title" name="title" type="text" placeholder="Title">
  <label for="np-body">Description</label>
  <textarea id="np-body" name="body" rows="4" placeholder="Description" aria-label="Description"></textarea>
  <button type="submit">${label}</button>
  <button type="button" data-action="arc:close">Cancel</button>
</form>`, { title: label });
    },
    'create-pr'({ form, el }) {
      const r = findRepo(ARC.route().params[0], ARC.route().params[1]);
      const draft = el.dataset.draft === 'yes';
      const title = String(form.title || '').trim();
      if (!title) { ARC.notify('Title is required'); return; }
      const base = ui().cmpBase || r.defaultBranch;
      const compare = ui().cmpCompare || base;
      if (base === compare) { ARC.notify('No changes'); return; }
      const nums = prsOf(r).map((p) => p.number);
      const number = (nums.length ? Math.max(...nums) : 0) + 1;
      const u = me();
      const pr = { id: ARC.uid('p'), repoId: r.id, number, title, body: form.body || '', state: draft ? 'Draft' : 'Open', base, compare, author: u.username, ago: 'just now', reviewers: [], reviews: [], comments: [], activity: [{ id: ARC.uid('pa'), text: u.username + ' opened this pull request', ago: 'just now' }], check: { status: 'pending', setter: null, ago: null }, inline: [] };
      S().prs.push(pr);
      ARC.save();
      ARC.closeDialog();
      ARC.navigate(prHash(r, pr));
    },
    'reviewers-menu'({ el }) {
      const r = findRepo(ARC.route().params[0], ARC.route().params[1]);
      const names = (S().memberships || []).filter((m) => m.orgId === r.orgId).map((m) => uname(m.userId));
      ARC.openPopover(el.parentElement, `<input type="text" id="reviewer-search" aria-label="Search" placeholder="Search" data-change="reviewers-search">
${names.map((n) => `<div role="option" data-action="request-reviewer" data-name="${esc(n)}">${esc(n)}</div>`).join('')}`, { kind: 'buttons' });
    },
    'reviewers-search'({ el }) {
      const q = String(el.value || '').toLowerCase();
      const pop = el.closest('[data-popover]');
      for (const o of pop.querySelectorAll('[role="option"]')) o.hidden = q && !o.textContent.toLowerCase().includes(q);
    },
    'request-reviewer'({ el }) {
      const { pr } = currentPr();
      if (!pr) return;
      const target = users().find((u) => u.username === el.dataset.name);
      pr.reviewers = pr.reviewers || [];
      if (target && !pr.reviewers.includes(target.id)) pr.reviewers.push(target.id);
      ARC.save();
      ARC.closePopover();
      ARC.render();
    },
    'remove-reviewer'({ id }) {
      const { pr } = currentPr();
      if (!pr) return;
      pr.reviewers = (pr.reviewers || []).filter((x) => x !== id);
      ARC.save();
      ARC.render();
    },
    'review-open'() {
      ARC.openDialog(`<form data-action="submit-review">
  <label for="rv-summary">Summary</label>
  <textarea id="rv-summary" name="summary" rows="4" aria-label="Summary"></textarea>
  <p><label><input type="radio" name="decision" value="Comment" checked> Comment</label></p>
  <p><label><input type="radio" name="decision" value="Approve"> Approve</label></p>
  <p><label><input type="radio" name="decision" value="Request changes"> Request changes</label></p>
  <button type="submit">Submit review</button>
  <button type="button" data-action="arc:close">Cancel</button>
</form>`, { title: 'Review changes' });
    },
    'submit-review'({ form }) {
      const { pr } = currentPr();
      const u = me();
      if (!pr || !u) return;
      const decision = form.decision || 'Comment';
      pr.reviews = pr.reviews || [];
      const rec = { id: ARC.uid('rv'), reviewer: u.username, status: decision === 'Approve' ? 'Approved' : (decision === 'Request changes' ? 'Changes requested' : 'Commented'), summary: form.summary || '', ago: 'just now' };
      const existing = pr.reviews.findIndex((x) => x.reviewer === u.username);
      if (existing >= 0) pr.reviews[existing] = rec;
      else pr.reviews.push(rec);
      ARC.save();
      ARC.closeDialog();
      ARC.render();
    },
    'line-comment'({ el }) {
      const { r, pr } = currentPr();
      if (!r || !pr) return;
      const head = branchHead(r, pr.compare);
      ui().lineTarget = { file: el.dataset.file, index: el.dataset.line, pr: pr.id, commit: head ? head.id : '' };
      ARC.openPopover(el.parentElement, `<textarea aria-label="Comment" rows="3"></textarea>
<button type="button" data-action="add-single-comment">Add single comment</button>
<button type="button" data-action="start-review">Start a review</button>`, { kind: 'buttons' });
    },
    'add-single-comment'({ el }) {
      const { pr } = currentPr();
      const pop = el.closest('[data-popover]');
      const body = String((pop && pop.querySelector('textarea') || {}).value || '').trim();
      if (!pr || !body || !ui().lineTarget) return;
      pr.inline = pr.inline || [];
      pr.inline.push({ id: ARC.uid('in'), author: (me() || {}).username, body, path: ui().lineTarget.file, commit: ui().lineTarget.commit, pending: false });
      ARC.save();
      ARC.closePopover();
      ARC.render();
    },
    'start-review'({ el }) {
      const { pr } = currentPr();
      const pop = el.closest('[data-popover]');
      const body = String((pop && pop.querySelector('textarea') || {}).value || '').trim();
      if (!pr || !body || !ui().lineTarget) return;
      pr.inline = pr.inline || [];
      pr.inline.push({ id: ARC.uid('in'), author: (me() || {}).username, body, path: ui().lineTarget.file, commit: ui().lineTarget.commit, pending: true });
      ARC.save();
      ARC.closePopover();
      ARC.render();
    },
    'check-change'({ value }) { ui().checkValue = value; },
    'save-check'({ el }) {
      const pr = (S().prs || []).find((p) => p.id === el.dataset.pr);
      const u = me();
      pr.check = { status: ui().checkValue || 'pending', setter: u ? u.username : null, ago: 'just now' };
      ARC.save();
      ARC.render();
    },
    'ready-for-review'({ el }) {
      const pr = (S().prs || []).find((p) => p.id === el.dataset.pr);
      pr.state = 'Open';
      pr.activity = pr.activity || [];
      pr.activity.push({ id: ARC.uid('pa'), text: 'Ready for review', ago: 'just now' });
      ARC.save();
      ARC.render();
    },
    'merge-pr'() { ui().mergeConfirm = true; ARC.render(); },
    'confirm-merge'({ el }) {
      const pr = (S().prs || []).find((p) => p.id === el.dataset.pr);
      const r = repos().find((x) => x.id === pr.repoId);
      const u = me();
      const blockers = mergeBlockers(pr, r);
      if (blockers.length) { ui().mergeError = blockers[0]; ARC.render(); return; }
      pr.state = 'Merged';
      pr.mergedBy = u ? u.username : '';
      pr.mergedCommit = ARC.uid('m').slice(-7);
      pr.activity = pr.activity || [];
      pr.activity.push({ id: ARC.uid('pa'), text: 'Merged this pull request', ago: 'just now' });
      const head = branchHead(r, pr.compare);
      const br = branchesOf(r).find((b) => b.name === pr.base);
      if (br && head) br.head = head.id;
      ui().mergeConfirm = false;
      ARC.save();
      ARC.render();
    },
    'close-pr'({ el }) {
      const pr = (S().prs || []).find((p) => p.id === el.dataset.pr);
      pr.state = 'Closed';
      ARC.save();
      ARC.render();
    },
    'reopen-pr'({ el }) {
      const pr = (S().prs || []).find((p) => p.id === el.dataset.pr);
      pr.state = 'Open';
      ARC.save();
      ARC.render();
    },
    'repo-filter'({ el }) { ui().repoFilter = el.value; ui().focus = 'find-repo'; ARC.save(); ARC.render(); },
    'repo-visibility'({ el }) { ui().repoVisibility = el.dataset.vis; ARC.save(); ARC.render(); },
    'code-path'({ el }) { ui().codePath = el.value; ui().focus = 'path-filter'; ARC.save(); ARC.render(); },
    'compare-run'() { ARC.render(); }
  }

function () {
    const id = ui().focus;
    if (id && !ARC.dialogOpen) {
      const el = document.getElementById(id);
      if (el && typeof el.focus === 'function') {
        el.focus();
        try { el.setSelectionRange(el.value.length, el.value.length); } catch (e) { /* not a text field */ }
      }
    }
  }

function diffSummary(files) {
    const a = files.reduce((n, f) => n + (f.additions || 0), 0);
    const d = files.reduce((n, f) => n + (f.deletions || 0), 0);
    return `${a} additions, ${d} deletions`;
  }

function commitsBetween(r, base, compare) {
    const baseHead = branchHead(r, base);
    const cmpHead = branchHead(r, compare);
    const out = [];
    let cur = cmpHead, guard = 0;
    while (cur && (!baseHead || cur.id !== baseHead.id) && guard++ < 50) { out.push(cur); cur = cur.parent ? commitById(cur.parent) : null; }
    return out;
  }

function repoHeader(r, active, opts) {
    const h = repoHash(r);
    const tabs = [['code', 'Code', h], ['issues', 'Issues', h + '/issues'], ['pulls', 'Pull requests', h + '/pulls'], ['settings', 'Settings', h + '/settings']];
    const u = me();
    const role = effectiveRole(r, u);
    const alt = (r.ownerType === 'user' && r.orgId && findOrg(r.orgId)) ? findOrg(r.orgId).name + '/' + r.name : '';
    const forkLine = r.sourceId ? (() => { const src = repos().find((x) => x.id === r.sourceId); return src ? `<p class="forked">Forked from <a href="${repoHash(src)}">${esc(src.name)}</a></p>` : ''; })() : '';
    const branch = (ui().branch && ui().branch[r.id]) || r.defaultBranch;
    const write = canWrite(r, u);
    const toolbar = `<div class="repo-toolbar">
  <span class="pick"><button type="button" data-action="branch-menu">Branch ${esc(branch)}</button></span>
  <span class="pick"><button type="button" data-action="clone-menu">Code</button></span>
  ${u ? `<span class="pick"><button type="button" data-action="fork-open">Fork</button></span>` : ''}
  ${write ? `<span class="pick"><button type="button" data-action="add-file-menu">Add file</button></span>` : ''}
</div>`;
    const common = `<h1>${esc(repoFull(r))}</h1>
${alt ? `<p class="repo-path">${esc(alt)}</p>` : ''}
<p>${marker(r)} ${role ? esc(role) + ' permission' : 'no permission'}</p>
<p>${esc(r.description || '')}</p>
${forkLine}
<nav class="repo-nav">${tabs.map(([k, label, href]) => `<a href="${href}"${active === k ? ' aria-current="page"' : ''}>${label}</a>`).join('')}</nav>`;
    if (active === 'code') return common + toolbar;
    return common;
  }

function findRepo(owner, name) {
    return repos().find((r) => r.name === name && ownerName(r) === owner) || null;
  }

function ownerName(r) {
    if (!r) return '';
    if (r.ownerType === 'org') { const o = findOrg(r.ownerId); return o ? o.name : r.ownerId; }
    return uname(r.ownerId) || r.ownerId;
  }

bindings.setup:
window.ARC = window.ARC || {};
ARC.esc = function (s) { return String(s == null ? '' : s); };
ARC.state = JSON.parse(JSON.stringify(window.SEED));
ARC.state.session = 'u1';
ARC.state.ui = ARC.state.ui || {};
ARC.state.ui.cmpBase = 'main';
ARC.state.ui.cmpCompare = 'onboarding';
ARC.save = function () {};
ARC.render = function () {};
ARC.navigate = function () {};
ARC.notify = function () {};
ARC.openDialog = function () {};
ARC.closeDialog = function () {};
ARC.openPopover = function () {};
ARC.closePopover = function () {};
ARC.dialogOpen = false;
ARC.uid = function (p) { return (p || 'x') + '-' + Math.random().toString(36).slice(2, 8); };
ARC.route = function () { return { name: 'r', params: ['alice-dev', 'acme-docs', 'pulls', 'compare'] }; };
ARC.currentUser = function () { return (ARC.state.users || []).find(function (u) { return u.id === ARC.state.session; }) || null; };

bindings.precondition:
const st = ARC.state;
const r1 = st.repos.find(function (r) { return r.id === 'r1'; });
assert.ok(r1, 'the seeded acme-docs repository exists');
assert.strictEqual(ARC.currentUser().username, 'alice-dev');
assert.strictEqual(st.ui.cmpBase, 'main');
assert.strictEqual(st.ui.cmpCompare, 'onboarding');
assert.ok(st.branches.some(function (b) { return b.repoId === 'r1' && b.name === 'main'; }));
assert.ok(st.branches.some(function (b) { return b.repoId === 'r1' && b.name === 'onboarding'; }));
const pair = st.prs.filter(function (p) { return p.repoId === 'r1' && p.base === 'main' && p.compare === 'onboarding' && (p.state === 'Open' || p.state === 'Draft'); });
assert.strictEqual(pair.length, 1, 'exactly one Open/Draft pull request already uses this base/compare pair');
assert.strictEqual(pair[0].state, 'Open');

bindings.check:
createPR({ form: { title: 'Second onboarding pull request', body: 'Duplicate of the open pull request.' }, el: { dataset: { draft: 'no' } } });
const st = ARC.state;
assert.strictEqual(st.prs.filter(function (p) { return p.title === 'Second onboarding pull request'; }).length, 0, 'reusing a Draft/Open base/compare pair must not create a second pull request');
assert.strictEqual(st.prs.filter(function (p) { return p.repoId === 'r1' && p.base === 'main' && p.compare === 'onboarding' && (p.state === 'Open' || p.state === 'Draft'); }).length, 1, 'exactly one Open/Draft pull request may exist for the pair');
st.ui.cmpBase = 'release';
st.ui.cmpCompare = 'feature-search';
createPR({ form: { title: 'Control pull request for an unused pair', body: '' }, el: { dataset: { draft: 'no' } } });
assert.strictEqual(st.prs.filter(function (p) { return p.title === 'Control pull request for an unused pair'; }).length, 1, 'control: the creation path does persist a pull request for an unused pair');
